<?php
namespace App\Http\Controllers\Admin;use App\Domain\Installation\WebsiteSettings;use App\Domain\Products\{ProductDependencyInspector,ProductManager,ProductRegistry,ProductRelationManager,ProductViewData};use App\Http\Controllers\{Controller,PublicSiteController};use App\Http\Requests\Products\SaveProductRequest;use App\Models\{Page,Product,ProductCategory,Solution};use Illuminate\Contracts\View\View;use Illuminate\Http\{RedirectResponse,Request,Response};use Illuminate\Support\Carbon;use Illuminate\Support\Str;use Illuminate\Validation\Rule;class ProductController extends Controller {public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'category'=>['nullable','integer'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without'],'template'=>['nullable',Rule::in(ProductRegistry::TEMPLATES)],'sort'=>['nullable','in:title,updated_at,published_at,display_order'],'direction'=>['nullable','in:asc,desc']]);$q=Product::with('category')->withCount('editions')->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['category']??null,fn($q,$v)=>$q->where('product_category_id',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['template']??null,fn($q,$v)=>$q->where('template',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only')$q->whereNotNull('archived_at');elseif(($f['archived']??'without')==='without')$q->whereNull('archived_at');return view('admin.products.index',['products'=>$q->orderBy($f['sort']??'display_order',$f['direction']??'asc')->paginate(20)->withQueryString(),'f'=>$f,'categories'=>ProductCategory::orderBy('display_order')->get(),'templates'=>ProductRegistry::TEMPLATES]);}public function create():View{return $this->editor(new Product);}public function store(SaveProductRequest $r,ProductManager $m):RedirectResponse{$p=$m->save($r->validated(),null,$r->user()->id);return redirect()->route('admin.products.edit',$p)->with('status','Draft product created.');}public function edit(Product $product):View{return $this->editor($product);}public function update(SaveProductRequest $r,Product $product,ProductManager $m):RedirectResponse{$m->save($r->validated(),$product,$r->user()->id);return back()->with('status','Product saved without changing publication state.');}private function editor(Product $p):View{if($p->exists)$p->load(['editions','featureGroups.features','benefits','specifications','galleryItems','useCases','integrations','relatedProducts','relatedSolutions','relatedPages']);return view('admin.products.editor',['product'=>$p,'categories'=>ProductCategory::where('is_active',true)->orderBy('display_order')->get(),'templates'=>ProductRegistry::TEMPLATES,'heroes'=>ProductRegistry::HERO_STYLES,'icons'=>ProductRegistry::ICONS,'editionTypes'=>ProductRegistry::EDITION_TYPES,'products'=>Product::whereKeyNot($p->id)->whereNull('archived_at')->orderBy('title')->get(),'solutions'=>Solution::whereNull('archived_at')->orderBy('title')->get(),'pages'=>Page::whereNull('archived_at')->orderBy('title')->get(),'dependencies'=>$p->exists?app(ProductDependencyInspector::class)->inspect($p):null]);}public function publish(Product $product,ProductManager $m):RedirectResponse{$m->publish($product);return back()->with('status','Product published.');}public function schedule(Request $r,Product $product,ProductManager $m):RedirectResponse{$v=$r->validate(['scheduled_for'=>['required','date']]);$tz=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$m->schedule($product,Carbon::parse($v['scheduled_for'],$tz)->utc()->toDateTimeString());return back()->with('status','Product scheduled.');}public function unpublish(Product $product,ProductManager $m):RedirectResponse{$m->unpublish($product);return back()->with('status','Product returned to draft.');}public function archive(Product $product,ProductManager $m):RedirectResponse{$m->archive($product);return back()->with('status','Product archived.');}public function restore(Product $product,ProductManager $m):RedirectResponse{$m->restore($product);return back()->with('status','Product restored to draft.');}public function duplicate(Request $r,Product $product,ProductManager $m):RedirectResponse{$copy=$m->duplicate($product,$r->user()->id);return redirect()->route('admin.products.edit',$copy)->with('status','Draft duplicate created.');}public function move(Product $product,string $direction,ProductManager $m):RedirectResponse{$m->move($product,$direction);return back();}public function relations(Request $r,Product $product,ProductRelationManager $m):RedirectResponse{$d=$r->validate(['related_product_ids'=>['array','max:6'],'related_product_ids.*'=>['integer','distinct','exists:products,id'],'related_solution_ids'=>['array','max:6'],'related_solution_ids.*'=>['integer','distinct','exists:solutions,id'],'related_page_ids'=>['array','max:6'],'related_page_ids.*'=>['integer','distinct','exists:pages,id']]);$m->sync($product,$d['related_product_ids']??[],$d['related_solution_ids']??[],$d['related_page_ids']??[]);return back()->with('status','Relations saved.');}public function preview(Request $r,Product $product,ProductViewData $d):Response{return response()->view('products.show',['product'=>$d->preview($product),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');}public function categories():View{return view('admin.products.categories',['categories'=>ProductCategory::withCount('products')->orderBy('display_order')->get()]);}public function storeCategory(Request $r,ProductManager $m):RedirectResponse{$m->saveCategory($this->categoryData($r));return back()->with('status','Category created.');}public function updateCategory(Request $r,ProductCategory $category,ProductManager $m):RedirectResponse{$m->saveCategory($this->categoryData($r,$category),$category);return back()->with('status','Category updated.');}public function moveCategory(ProductCategory $category,string $direction,ProductManager $m):RedirectResponse{$m->moveCategory($category,$direction);return back();}private function categoryData(Request $r,?ProductCategory $c=null):array{$raw=(string)$r->input('slug');$r->merge(['slug'=>(str_contains($raw,'/')||str_contains($raw,'\\')||str_contains($raw,'..'))?'':Str::slug(Str::lower($raw)),'is_active'=>$r->boolean('is_active')]);return $r->validate(['name'=>['required','string','max:120'],'slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique('product_categories')->ignore($c)],'description'=>['nullable','string','max:2000'],'is_active'=>['boolean']]);}}